#include <algorithm>
using namespace std;

#define long long long

struct HashKey {
    long long val;
    HashKey(long long v) : val(v) {}
    bool operator==(const HashKey &other) const {
        return val == other.val;
    }
};

struct HashKeyHasher {
    size_t operator()(const HashKey& k) const {
        return hash<long long>()(k.val);
    }
};

class Test {
public:
    int R, C;
    long ch[61][61];
    int cntA[61], cntB[61];
    long best;
    string str;
    unordered_map<long, long> cache;
    unordered_set<long> tried;

    void start() {
        R = readInt();
        C = readInt();

        for (int i = 0; i <= 2 * (R + C); i++) {
            for (int j = 0; j <= i; j++) {
                if (j == 0 || j == i) ch[i][j] = 1;
                else ch[i][j] = ch[i - 1][j - 1] + ch[i - 1][j];
            }
        }

        long x = 0, y = 0;
        int v1 = R + C, v2 = R + C;
        while (v1 >= R && v2 >= R) {
            if (x > y) {
                long cur = ch[v1][R] - ch[v1 - 1][R];
                long other = ch[v2][R];
                y += cur * other;
                v1--;
            } else {
                long cur = ch[v2][R] - ch[v2 - 1][R];
                long other = ch[v1][R];
                x += cur * other;
                v2--;
            }
        }
        best = abs(x - y);
        dfs(0, 0, R + C, R + C);
        str = readString();

        for (int i = 0; i < 2 * (R + C); i++) {
            cntA[i + 1] = cntA[i] + (str[i] == 'A' ? 1 : 0);
            cntB[i + 1] = cntB[i] + (str[i] == 'B' ? 1 : 0);
        }

        long ans = solve(0, 0, R + C, R + C);
        cout << ans << "\n";
    }

    int readInt() {
        int ans = 0;
        bool neg = false;
        bool start = false;
        char c;
        while (cin.get(c)) {
            if (c == '-') {
                start = true;
                neg = true;
                continue;
            }
            if (c >= '0' && c <= '9') {
                start = true;
                ans = ans * 10 + c - '0';
            } else if (start) {
                break;
            }
        }
        return neg ? -ans : ans;
    }

    long readLong() {
        long ans = 0;
        bool neg = false;
        bool start = false;
        char c;
        while (cin.get(c)) {
            if (c == '-') {
                start = true;
                neg = true;
                continue;
            }
            if (c >= '0' && c <= '9') {
                start = true;
                ans = ans * 10 + c - '0';
            } else if (start) {
                break;
            }
        }
        return neg ? -ans : ans;
    }

    string readString() {
        string b;
        char c;
        bool start = false;
        while (cin.get(c)) {
            if (!isspace(c)) {
                start = true;
                b.push_back(c);
            } else if (start) {
                break;
            }
        }
        return b;
    }

    long dfs(long x, long y, int v1, int v2) {
        long diff = abs(x - y);
        if (best <= 1 || diff - ch[v1][R] * ch[v2][R] >= best) return best + 1; // return a large number
        if (v1 == R - 1 && v2 == R - 1) {
            if (diff < best) best = diff;
            return best;
        }
        long key = x * 1000000 + v1 * 1000 + v2;
        if (tried.count(key) > 0) return best + 1;
        if (v1 >= R) {
            long cur = ch[v1][R] - ch[v1 - 1][R];
            long other = ch[v2][R];
            long res = dfs(x, y + cur * other, v1 - 1, v2);
            if (res < best) best = res;
        }
        if (v2 >= R) {
            long cur = ch[v2][R] - ch[v2 - 1][R];
            long other = ch[v1][R];
            long res = dfs(x + cur * other, y, v1, v2 - 1);
            if (res < best) best = res;
        }
        tried.insert(key);
        return best;
    }

    long solve(long x, long y, int v1, int v2) {
        long diff = abs(x - y);
        if (diff - ch[v1][R] * ch[v2][R] > best) return 0;
        long key = x * 10000 + v1 * 100 + v2;
        if (cache.count(key)) return cache[key];
        if (v1 < R || v2 < R) {
            if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
                int sum = v1 + v2;
                v1 -= cntA[sum];
                v2 -= cntB[sum];
                return ch[v1 + v2][v1];
            }
            return 0;
        }
        long ans = 0;
        char c = str[v1 + v2 - 1];
        if (c != 'B') {
            long cur = ch[v1][R] - ch[v1 - 1][R];
            long other = ch[v2][R];
            ans += solve(x, y + cur * other, v1 - 1, v2);
        }
        if (c != 'A') {
            long cur = ch[v2][R] - ch[v2 - 1][R];
            long other = ch[v1][R];
            ans += solve(x + cur * other, y, v1, v2 - 1);
        }
        cache[key] = ans;
        return ans;
    }
};

